/* ---------- Room code copy ---------- */
const _onlineRoomPanelV476Base=onlineRoomPanel;
onlineRoomPanel=function(){const html=_onlineRoomPanelV476Base();if(!(ROOM||roomInfo()))return html;const box=document.createElement('div');box.innerHTML=html;const row=box.querySelector('.room-panel .btn-row'),link=box.querySelector('#copyRoomLink');if(row&&link&&!box.querySelector('#copyRoomCodeV476'))link.insertAdjacentHTML('beforebegin','<button class="btn copy-code-v476" id="copyRoomCodeV476">SAO CHÉP MÃ GAME</button>');return box.innerHTML};
const _bindLoginV476Base=bindLogin;
bindLogin=function(){_bindLoginV476Base();const b=document.getElementById('copyRoomCodeV476');if(b)b.onclick=async()=>{const ri=ROOM||roomInfo();if(!ri)return;try{await navigator.clipboard.writeText(ri.code);b.textContent='✓ ĐÃ SAO CHÉP MÃ'}catch(e){prompt('Sao chép mã game:',ri.code)}}};

/* ---------- Branch defaults, clearer stepper and purchase receipt ---------- */
function branchReceiptKeyV476(name,s){return`tt_v476_branch_receipt:${ROOM?.code||roomInfo()?.code||'offline'}:${name}:R${s.round}`}
function readBranchReceiptV476(name,s){try{const x=JSON.parse(sessionStorage.getItem(branchReceiptKeyV476(name,s))||'null');return x&&Date.now()-Number(x.at)<120000?x:null}catch(e){return null}}
function writeBranchReceiptV476(name,s,x){try{sessionStorage.setItem(branchReceiptKeyV476(name,s),JSON.stringify({...x,at:Date.now()}))}catch(e){}}
const _branchPurchaseCardV476Base=branchPurchaseCard;
branchPurchaseCard=function(name,s){const html=_branchPurchaseCardV476Base(name,s);if(!html)return html;const box=document.createElement('div');box.innerHTML=html;const card=box.firstElementChild,res=card?.querySelector('#branchRes'),p=s.players?.[name];if(!card||!p)return html;if(res){const d=readBranchDraftV47(name,s),chosen=d.res&&RES[d.res]?d.res:p.businessId;if(chosen&&[...res.options].some(o=>o.value===chosen))res.value=chosen}card.querySelectorAll('.branchQtyDeltaV472').forEach(b=>{b.innerHTML=Number(b.dataset.delta)<0?'− <span>GIẢM</span>':'+ <span>TĂNG</span>'});const receipt=['P2','P3'].includes(s.phase)?readBranchReceiptV476(name,s):null;if(receipt)card.insertAdjacentHTML('beforeend',`<div class="branch-success-v476">✓ Đã mua thành công <b>${receipt.qty}</b> chi nhánh ${RES[receipt.res]?.icon||''} <b>${esc(RES[receipt.res]?.label||receipt.res)}</b>, tổng giá ${receipt.cost}M.</div>`);return card.outerHTML};
const _bindBranchUIV476Base=bindBranchUI;
bindBranchUI=function(name){_bindBranchUIV476Base(name);const s=load(),p=s.players?.[name],res=document.getElementById('branchRes'),qty=document.getElementById('branchQty'),buy=document.getElementById('buyBranch');if(!p||!res||!qty)return;const d=readBranchDraftV47(name,s);if(!d.res||!RES[d.res]){res.value=p.businessId;writeBranchDraftV47(name,{res:res.value,qty:qty.value},s);res.dispatchEvent(new Event('change',{bubbles:true}))}if(buy&&!buy.dataset.v476Receipt){buy.dataset.v476Receipt='1';const old=buy.onclick;buy.onclick=e=>{const before=load(),bp=before.players?.[name],beforeCount=branchSummary(bp)[res.value]||0,r=res.value,q=Number(qty.value)||0,base=Math.max(0,Number(before.branchMarket?.price)||0),cost=(r===bp?.businessId?base:base*3)*q,out=old?.call(buy,e),after=load(),afterCount=branchSummary(after.players?.[name])[r]||0;if(afterCount>beforeCount){writeBranchReceiptV476(name,after,{res:r,qty:afterCount-beforeCount,cost});render()}return out}}};

/* ---------- Host finance ordering and bank overview ---------- */
hostSecretsCard=function(s){const show=!!session?.showHostSecrets,prices=bankPriceMapV475(s),rows=Object.entries(s.players||{}).map(([name,p])=>{const inv=RESOURCE_KEYS.filter(k=>(Number(p.res?.[k])||0)>0),stock=roundMoneyV475(RESOURCE_KEYS.reduce((sum,k)=>sum+(Number(p.res?.[k])||0)*prices[k],0)),gross=roundMoneyV475((Number(p.money)||0)+stock),debt=roundMoneyV475(bankBalanceV475(p));return{name,p,inv,stock,gross,debt,net:roundMoneyV475(gross-debt)}}).sort((a,b)=>b.gross-a.gross||b.p.money-a.p.money||a.name.localeCompare(b.name,'vi'));return`<div class="card"><div class="split"><div><div class="title" style="margin:0">Tài chính & tồn kho người chơi</div><div class="muted">Xếp theo tổng tiền mặt + tài nguyên quy đổi hiện hành, từ cao xuống thấp.</div></div><button class="btn ${show?'warn':'secondary'}" id="toggleHostSecrets">${show?'🙈 ẨN THÔNG TIN':'👁️ HIỆN TÀI CHÍNH / TỒN KHO'}</button></div>${show?`<div class="host-secret-grid">${rows.map((x,i)=>{const br=branchSummary(x.p);return`<div class="host-secret-card"><div class="split"><div style="display:flex;align-items:center;gap:8px"><span class="host-rank-v476">${i+1}</span><b>${esc(x.name)}</b></div><span class="badge">${x.p.company}</span></div><div class="secret-money">${x.p.money}M</div><div class="secret-value">Tồn kho hiện hành ≈ ${x.stock}M · <b>Tổng ≈ ${x.gross}M</b></div>${x.debt>0?`<div class="host-debt-v476">Dư nợ ${x.debt}M · Tài sản ròng ≈ ${x.net}M</div>`:''}<div class="inventory-chips">${x.inv.length?x.inv.map(k=>`<span class="inventory-chip">${RES[k].icon} ${RES[k].label} ×${x.p.res[k]}</span>`).join(''):'<span class="muted tiny">Không còn tài nguyên</span>'}</div>${Object.keys(br).length?`<div class="branch-rule"><b>Chi nhánh:</b> ${Object.entries(br).map(([k,v])=>`${RES[k].icon}${RES[k].label} ×${v}`).join(' · ')}</div>`:''}</div>`}).join('')}</div>`:'<div class="footer-note">Đang ẩn tiền, tồn kho và giá trị tài sản tham chiếu.</div>'}</div>`};
function hostBankOverviewV476(s){if(!s.bank?.enabled)return'';const rows=Object.entries(s.players||{}).map(([name,p])=>({name,p,loan:normalizeBankLoanV475(p,s)})).filter(x=>x.loan.active||x.loan.balance>0).sort((a,b)=>b.loan.balance-a.loan.balance);return`<div class="card host-bank-overview-v476"><div class="split"><div><div class="title">🏦 Theo dõi vay nợ Ngân hàng Cơ</div><div class="muted tiny">Dư nợ gồm cả gốc và lãi đã cộng đến thời điểm hiện tại.</div></div><span class="badge">${rows.length} NGƯỜI ĐANG NỢ</span></div>${rows.length?`<div style="margin-top:8px">${rows.map(x=>`<div class="host-bank-row-v476"><b>${esc(x.name)}</b><span>Dư nợ<br><b>${roundMoneyV475(x.loan.balance)}M</b></span><span>Gói<br><b>${bankModeLabelV475(x.loan.mode)}</b></span><span>Lãi cộng<br><b>${roundMoneyV475(x.loan.totalInterestAccrued)}M</b></span><span>Đã trả<br><b>${roundMoneyV475(x.loan.totalPaid)}M</b></span></div>`).join('')}</div>`:'<div class="footer-note">Chưa có người chơi nào mang dư nợ.</div>'}</div>`}

/* ---------- Safe trade reservations ---------- */
function tradeRootV476(s,t){return(s.trades||[]).find(x=>String(x.id)===String(t?.rootId))||t}
function heldReservationV476(root,seller=null){const r=root?.reservationV476;return !!(r&&r.status==='held'&&(!seller||r.seller===seller))}
function reserveTradeInventoryV476(s,root,seller){if(!root||root.reservationV476)return true;const p=s.players?.[seller],qty=Math.max(0,Number(root.qty)||0);if(!p||(Number(p.res?.[root.res])||0)<qty)return false;p.res[root.res]=Number(p.res[root.res]||0)-qty;root.reservationV476={status:'held',seller,res:root.res,qty,heldAt:Date.now()};return true}
function releaseTradeReservationV476(s,root,reason='closed'){const r=root?.reservationV476;if(!r||r.status!=='held')return false;const p=s.players?.[r.seller];if(p){p.res[r.res]=Number(p.res?.[r.res]||0)+Number(r.qty||0)}r.status='released';r.releasedAt=Date.now();r.releaseReason=reason;return true}
function consumeTradeReservationV476(root){const r=root?.reservationV476;if(r&&r.status==='held'){r.status='consumed';r.consumedAt=Date.now();return true}return false}

sendTradeOffer=async function(name){
  reserveTradeSeqV47();const s=load();if(s.phase!=='P3')return;persistTradeDraft(name);const d=tradeDraft(name,s),kind=d.kind,target=d.to,res=d.res,qty=d.qty,price=d.money,message=String(d.message||'').trim(),actor=s.players[name];
  if(kind==='buy'&&actor.money<price){alert('Bạn không đủ tiền cho đề nghị mua này.');return}if(kind==='sell'&&(Number(actor.res?.[res])||0)<qty){alert('Bạn không đủ tài nguyên để bán.');return}
  const verb=kind==='buy'?'MUA':'BÁN',who=target==='ALL'?'TẤT CẢ':target,ok=await uiConfirmV46({title:`XÁC NHẬN GỬI ${verb}`,tone:kind==='buy'?'buy':'sell',rows:[['Tài nguyên',`${RES[res].icon} ${RES[res].label} ×${qty}`],['Đối tác',who],['Tổng giá',`${price}M`]],message:kind==='sell'?(message?message+'\n\n':'')+'Tài nguyên sẽ được giữ riêng ngay khi gửi và tự hoàn lại nếu giao dịch không thành.':message,confirmText:`GỬI ${verb}`});if(!ok)return;
  const id=s.seq++,all=target==='ALL',trade={schema:2,id,rootId:id,round:s.round,mode:all?'all':'direct',originType:kind,initiator:name,target:all?'ALL':target,res,qty,price,proposer:name,recipient:all?null:target,buyer:kind==='buy'?name:(all?null:target),seller:kind==='sell'?name:(all?null:target),stage:'root',status:'pending',responses:{},branchWith:all?null:target,createdAt:Date.now(),message};
  if(kind==='sell'&&!reserveTradeInventoryV476(s,trade,name)){alert('Tồn kho vừa thay đổi, không thể giữ đủ tài nguyên cho đơn bán.');return}s.trades.push(trade);logPush(s,`${name} gửi #${id} ${verb} ${RES[res].label} ×${qty} ${all?'cho ALL':`với ${target}`} · ${price}M${kind==='sell'?' (đã giữ hàng)':''}.`);save(s);render()
};

executeTrade=function(s,t,actor){
  const parties=tradeParties(t,actor),buyer=parties.buyer,seller=parties.seller;if(!buyer||!seller||buyer===seller)return'Không xác định được hai bên giao dịch.';const bp=s.players?.[buyer],sp=s.players?.[seller];if(!bp||!sp)return'Người chơi không còn hợp lệ.';const root=tradeRootV476(s,t),reserved=heldReservationV476(root,seller);
  if(Number(bp.money)<Number(t.price))return`${buyer} không còn đủ ${t.price}M.`;if(!reserved&&(Number(sp.res?.[t.res])||0)<Number(t.qty))return`${seller} không còn đủ ${RES[t.res].label}×${t.qty}.`;
  bp.money=roundMoneyV475(Number(bp.money)-Number(t.price));sp.money=roundMoneyV475(Number(sp.money)+Number(t.price));if(reserved)consumeTradeReservationV476(root);else sp.res[t.res]=Number(sp.res[t.res]||0)-Number(t.qty);bp.res[t.res]=Number(bp.res[t.res]||0)+Number(t.qty);
  t.buyer=buyer;t.seller=seller;t.status='accepted';t.acceptedAt=Date.now();for(const x of s.trades||[])if(x.rootId===t.rootId&&x.id!==t.id&&x.status==='pending')x.status='closed';if(root.id!==t.id&&['pending','superseded'].includes(root.status))root.status='closed';if(root.responses)for(const k of Object.keys(root.responses))root.responses[k]='closed';logPush(s,`✅ Giao dịch #${t.id}: ${buyer} mua ${RES[t.res].icon} ${RES[t.res].label} ×${t.qty} từ ${seller} với ${t.price}M.`);return null
};

declineTrade=withNegotiationCommitV465(async function(name,id){const s=load(),t=s.trades.find(x=>x.id===id);if(!canRespondToTrade(name,t)){render();return}const root=tradeRootV476(s,t);if(t.mode==='all'&&t.stage==='root'){t.responses=t.responses||{};t.responses[name]='declined';logPush(s,`${name} từ chối đề nghị ALL #${t.id}.`)}else{t.status='declined';if(root.mode==='all'&&t.branchWith){root.responses=root.responses||{};root.responses[t.branchWith]='declined';for(const x of s.trades)if(x.rootId===t.rootId&&x.branchWith===t.branchWith&&x.id!==t.id&&x.status==='pending')x.status='closed'}else{for(const x of s.trades)if(x.rootId===t.rootId&&x.id!==t.id&&x.status==='pending')x.status='closed';releaseTradeReservationV476(s,root,'declined')}logPush(s,`${name} từ chối đề nghị #${t.id}.`)}save(s);await closeNegotiationThread(name,t,'declined');render()});

sendCounterOffer=withNegotiationCommitV465(async function(name,id,newPrice,message=''){reserveTradeSeqV47();const s=load(),t=s.trades.find(x=>x.id===id);newPrice=Number(newPrice);if(s.phase!=='P3'){alert('Chỉ thương lượng trong P3.');return}if(!Number.isFinite(newPrice)||newPrice<0){alert('Giá thương lượng không hợp lệ.');return}if(!canRespondToTrade(name,t)){render();return}const parties=tradeParties(t,name),buyer=parties.buyer,seller=parties.seller;if(!buyer||!seller)return;const root=tradeRootV476(s,t),sellerCovered=heldReservationV476(root,seller);if(name===buyer&&Number(s.players[name].money)<newPrice){alert('Bạn không đủ tiền cho giá thương lượng này.');return}if(name===seller&&!sellerCovered&&(Number(s.players[name].res?.[t.res])||0)<Number(t.qty)){alert('Bạn không còn đủ tài nguyên cho đề nghị này.');return}const other=name===buyer?seller:buyer;const ok=await uiConfirmV46({title:'GỬI PHẢN HỒI THƯƠNG LƯỢNG?',rows:[['Vai trò',name===buyer?'MUA':'BÁN'],['Giá mới',`${newPrice}M`],['Gửi đến',other]],message:String(message||'').trim(),confirmText:'GỬI GIÁ MỚI'});if(!ok)return;if(name===seller&&!sellerCovered&&!reserveTradeInventoryV476(s,root,seller)){alert('Không thể giữ đủ tài nguyên cho phản hồi bán này.');return}if(String(message||'').trim()){try{await sendNegotiationMessage(name,t,message)}catch(e){alert('Không gửi được tin nhắn: '+(e.message||e));return}}const branchWith=root.mode==='all'?(root.initiator===name?other:name):(t.branchWith||other);if(t.mode==='all'&&t.stage==='root'){t.responses=t.responses||{};t.responses[name]='negotiating'}else{t.status='superseded';if(root.mode==='all'){root.responses=root.responses||{};root.responses[branchWith]='negotiating'}}const nid=s.seq++;s.trades.push({schema:2,id:nid,rootId:t.rootId,round:s.round,mode:t.mode,originType:t.originType,initiator:root.initiator,target:root.target,res:t.res,qty:t.qty,price:newPrice,proposer:name,recipient:other,buyer,seller,stage:'counter',status:'pending',responses:{},branchWith,createdAt:Date.now(),parentId:t.id});logPush(s,`💬 ${name} thương lượng lại giao dịch #${t.rootId}: ${newPrice}M.`);save(s);render();setTimeout(()=>refreshNegotiationHistories(name),120)});

expireOpenTrades=function(s,round){const roots=new Set();for(const t of s.trades||[])if(Number(t.round)===Number(round)){roots.add(String(t.rootId));if(t.status==='pending')t.status='expired'}for(const id of roots){const group=(s.trades||[]).filter(t=>String(t.rootId)===id),root=group.find(t=>String(t.id)===id)||group[0];if(!group.some(t=>t.status==='accepted'))releaseTradeReservationV476(s,root,'expired')}};

/* Reject a second simultaneous acceptance of the same ALL offer during CAS merge. */
const _rebasePlayerStateV476Base=rebasePlayerStateV47;
rebasePlayerStateV47=function(base,local,latest){let safe=local;const newly=(local.trades||[]).filter(t=>t.status==='accepted'&&(base.trades||[]).find(x=>String(x.id)===String(t.id))?.status!=='accepted');const conflicts=new Set(newly.filter(t=>(latest.trades||[]).some(x=>String(x.rootId)===String(t.rootId)&&x.status==='accepted')).map(t=>String(t.rootId)));if(conflicts.size){safe=deep(local);safe.players=deep(base.players);safe.log=deep(base.log||[]);safe.trades=(safe.trades||[]).filter(t=>!conflicts.has(String(t.rootId)));for(const t of base.trades||[])if(conflicts.has(String(t.rootId)))safe.trades.push(deep(t))}return _rebasePlayerStateV476Base(base,safe,latest)};

/* ---------- Trade presentation ---------- */
function tradePriorityV476(t){if(t.stage==='counter')return 2;if(t.mode==='direct')return 1;return 3}
function tradeSortV476(a,b){return tradePriorityV476(a)-tradePriorityV476(b)||(Number(b.createdAt)||Number(b.id)||0)-(Number(a.createdAt)||Number(a.id)||0)}
tradeSummary=function(t,viewer){const p=tradeParties(t,viewer),resource=`${RES[t.res]?.icon||''} ${esc(RES[t.res]?.label||t.res)} ×${Number(t.qty)||0}`,you=x=>x===viewer?'<span class="you-v476">BẠN</span>':`<b>${esc(x||'?')}</b>`;if(t.mode==='all'&&t.stage==='root')return t.originType==='sell'?`${you(t.initiator)} đang <b>BÁN</b> ${resource} cho <b>TẤT CẢ</b>.`:`${you(t.initiator)} đang <b>MUA</b> ${resource} từ <b>TẤT CẢ</b>.`;return t.proposer===p.buyer?`${you(t.proposer)} đang đề nghị <b>MUA</b> ${resource} từ ${you(p.seller)}.`:`${you(t.proposer)} đang đề nghị <b>BÁN</b> ${resource} cho ${you(p.buyer)}.`};
negotiationHistoryBox=function(name,t,archive=false){const other=negotiationOther(name,t);if(!other)return'';const root=tradeRootV476(load(),t),initial=root?.message?`<div class="neg-msg ${root.initiator===name?'mine':''}"><span class="who">${esc(root.initiator)}</span><span>${esc(root.message)}</span><span class="when">lời nhắn ban đầu</span></div>`:'';return`<div class="${archive?'':'neg-chat neg-response-v476'} ${initial?'':'empty-v476'}"><div class="${archive?'':'neg-chat-head'}">${archive?'':`<b>💬 Phản hồi thương lượng với ${esc(other)}</b><span class="tiny muted">#${t.rootId}</span>`}</div>${initial}<div class="negotiation-history" data-neg-root="${t.rootId}" data-neg-other="${esc(other)}"></div></div>`};
renderNegotiationMessages=function(el,rows,name){const chosen=(rows||[]).slice(-2);const chat=el.closest('.neg-chat');if(!chosen.length){el.innerHTML='';if(!chat?.querySelector('.neg-msg'))chat?.classList.add('empty-v476');return}chat?.classList.remove('empty-v476');el.innerHTML=chosen.map(m=>`<div class="neg-msg ${m.sender_name===name?'mine':''}"><span class="who">${esc(m.sender_name)}</span><span>${esc(m.body)}</span><span class="when">${new Date(m.created_at).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})}</span></div>`).join('');el.scrollTop=el.scrollHeight};
incomingTradeCard=function(name,t){const broadcast=t.mode==='all'&&t.stage==='root',counter=t.stage==='counter',s=load(),d=counterDraft(name,t.id,s),open=!!d.open,price=d.price??t.price,msg=d.message||'',root=tradeRootV476(s,t),channel=counter?'PHẢN HỒI THƯƠNG LƯỢNG':broadcast?'ĐƠN CHUNG / ALL':'ĐƠN RIÊNG';return`<div data-trade-id="${t.id}" class="trade incoming trade-v476 ${counter?'trade-counter-v476':broadcast?'trade-broadcast-v476':'trade-direct-v476'}"><div class="split"><div>${tradeTypeBadge(t)} <span class="trade-channel-v476">${channel}</span></div><span class="trade-status">#${t.id}</span></div><div class="trade-summary-v476">${tradeSummary(t,name)}</div><div class="trade-price-v476"><span>TỔNG GIÁ ĐỀ NGHỊ</span><strong>${Number(t.price)||0}M</strong></div>${t.message?`<div class="trade-message-note">💬 <b>Lời nhắn:</b> ${esc(t.message)}</div>`:''}${heldReservationV476(root)?`<div class="trade-reserved-v476">🔒 Tài nguyên của bên bán đang được hệ thống giữ riêng cho giao dịch này.</div>`:''}${negotiationHistoryBox(name,t)}<div class="btn-row" style="margin-top:9px"><button class="btn good acceptTrade" data-id="${t.id}">${acceptLabel(name,t)}</button><button class="btn bad declineTrade" data-id="${t.id}">TỪ CHỐI</button><button class="btn secondary negotiateTrade" data-id="${t.id}">💬 THƯƠNG LƯỢNG</button></div><div class="counter-panel ${open?'':'hidden'}" id="counterPanel-${t.id}"><div class="field" style="margin:0"><label>Giá mới (M)</label><input id="counterPrice-${t.id}" type="number" min="0" value="${esc(price)}"></div><div class="field"><label>Tin nhắn</label><textarea id="counterMessage-${t.id}" maxlength="1000">${esc(msg)}</textarea></div><button class="btn secondary big sendCounter" data-id="${t.id}">GỬI GIÁ MỚI + TIN NHẮN</button></div></div>`};
tradeInbox=function(name,s){const inc=(s.trades||[]).filter(t=>Number(t.round)===Number(s.round)&&isIncomingTrade(name,t)).sort(tradeSortV476),recent=(s.trades||[]).filter(t=>tradeRelevant(name,t)).sort((a,b)=>(Number(b.createdAt)||Number(b.id)||0)-(Number(a.createdAt)||Number(a.id)||0)).slice(0,10);return`<div class="card" id="tradeInboxCardV463"><div class="split"><div class="title">Đề nghị giao dịch</div>${inc.length?`<span class="tap-badge">${inc.length} CẦN PHẢN HỒI</span>`:''}</div><div class="tiny muted" style="margin:4px 0 9px">Ưu tiên: đơn riêng → phản hồi thương lượng → đơn chung. Mới nhất nằm trên.</div><div class="stack">${inc.map(t=>incomingTradeCard(name,t)).join('')}</div>${recent.length?`<div class="footer-note"><b>Lịch sử gần đây · mới nhất trước</b><br>${recent.map(t=>`#${t.id} ${tradeHistoryText(t,name)} — <b>${statusVi(t.status)}</b>`).join('<br>')}</div>`:''}${negotiationArchive(name,s)}</div>`};

