bindBidInputsV475=function(name){document.querySelectorAll('.v475-bid-input').forEach(input=>{const pid=input.dataset.project;const onInput=()=>{let v=String(input.value||'').replace(/[^0-9.,]/g,'').replace(/,/g,'.'),parts=v.split('.');if(parts.length>2)v=parts.shift()+'.'+parts.join('');parts=v.split('.');if(parts[1]?.length>1)v=parts[0]+'.'+parts[1].slice(0,1);input.value=v;writeBidDraftV475(name,pid,v,load());refreshBidValidationV475(name,pid)};input.addEventListener('input',onInput);input.addEventListener('change',onInput);refreshBidValidationV475(name,pid)});document.querySelectorAll('.submitBidV475').forEach(b=>b.onclick=()=>submitSealedBidV475(name,b.dataset.project).catch(e=>alert('Không gửi được giá chào: '+(e.message||e))))};
submitSealedBidV475=async function(name,pid){const s=load(),p=s.players?.[name],a=auctionState(s,pid),x=bidInputStateV475(name,pid,s);if(!p||!a||!ROOM?.id)return;if(!x.valid){alert(`Giá chào phải từ 1M đến ngân sách tối đa ${x.max}M; được dùng một chữ số thập phân.`);x.input?.focus({preventScroll:true});if(x.input)placeCaretAtEndV472(x.input);return}const ok=await uiConfirmV46({title:'GỬI GIÁ CHÀO KÍN?',rows:[['Dự án',pid],['Đối thủ',(a.participants||[]).filter(n=>n!==name).join(' · ')],['Giá chào',`${x.amount}M`],['Ngân sách tối đa',`${x.max}M`]],message:'Giá hợp lệ thấp nhất thắng. Sau khi gửi, bạn không thể sửa trong vòng giá này.',confirmText:'GỬI GIÁ CHÀO'});if(!ok)return;const {error}=await SB.rpc('submit_project_auction_bid',{p_room_id:ROOM.id,p_round:s.round,p_project_id:pid,p_bid:x.amount,...negotiationRpcAuth(name)});if(error){const m=String(error.message||'');if(m.includes('BID_ALREADY_SUBMITTED')){setAuctionSubmittedLocal(name,s,pid,a.bidRound,true);render();return}if(m.includes('BID_ABOVE_PROJECT_BUDGET'))throw new Error(`Giá chào vượt ngân sách ${x.max}M.`);if(m.includes('BID_BELOW_PROJECT_START_PRICE'))throw new Error('Máy chủ vẫn đang dùng luật giá sàn cũ. Hãy chạy file SQL V4.7.6.');throw error}setAuctionSubmittedLocal(name,s,pid,a.bidRound,true);writeBidDraftV475(name,pid,'',s);logPush(s,`${name} đã gửi giá chào kín cho ${pid}.`);save(s);render()};

