function rowsForHostBidV476(s,pid){const a=auctionState(s,pid);return HOST_BIDS_V476.filter(x=>String(x.project_id)===String(pid)&&Number(x.bid_round)===Number(a?.bidRound||0)).sort((a,b)=>Number(a.bid_amount)-Number(b.bid_amount)||String(a.player_name).localeCompare(String(b.player_name),'vi'))}
function liveBidHtmlV476(s,pid){const rows=rowsForHostBidV476(s,pid);if(HOST_BIDS_ERROR_V476)return`<div class="live-bids-v476 danger"><b>Chưa đọc được giá trực tiếp.</b><div class="tiny">${esc(HOST_BIDS_ERROR_V476)}</div></div>`;return`<div class="live-bids-v476"><b>📡 Giá đã gửi · thấp nhất ở trên</b>${rows.length?rows.map((x,i)=>`<div class="live-bid-row-v476"><span class="live-bid-no-v476">${i+1}</span><b>${esc(x.player_name)}</b><span class="live-bid-price-v476">${Number(x.bid_amount)}M</span></div>`).join(''):'<div class="tiny muted" style="margin-top:6px">Chưa có người gửi giá ở vòng này.</div>'}</div>`}
hostP5AuctionPanel=function(s){const contested=projects(s).map(pr=>({pr,parts:eligibleProjectContenders(s,pr.id)})).filter(x=>x.parts.length>1);if(!contested.length)return`<div class="auction-panel"><b>⚔️ Kiểm tra cạnh tranh</b><div class="auction-wait">Không có dự án nào có từ 2 người cùng đủ điều kiện.</div></div>`;return`<div class="auction-panel"><div class="split"><b>⚔️ ĐẤU THẦU KÍN — GIÁ THẤP NHẤT THẮNG</b><span class="badge">${contested.length} dự án</span></div><div class="v475-procurement-note">Host được xem danh sách giá đang gửi theo thời gian thực; người chơi vẫn không thấy giá của nhau.</div>${contested.map(({pr,parts})=>{const a=auctionState(s,pr.id);return`<div class="auction-row"><div class="split"><div><b>${esc(pr.id)} · ${esc(pr.name)}</b><div class="tiny muted">${(a?.participants||parts).map(esc).join(' ↔ ')} · tối đa ${Number(pr.reward)||0}M</div></div>${a?`<span class="badge auction-open">ĐANG MỞ · VÒNG #${a.bidRound||1}</span>`:`<button class="btn warn openAuctionBtn" data-project="${esc(pr.id)}">MỞ ĐẤU THẦU</button>`}</div>${a?`<div data-v476-live-bids="${esc(pr.id)}">${liveBidHtmlV476(s,pr.id)}</div>`:''}</div>`}).join('')}</div>`};
function patchHostLiveBidsV476(){if(session?.role!=='host')return;const s=load();document.querySelectorAll('[data-v476-live-bids]').forEach(el=>{el.innerHTML=liveBidHtmlV476(s,el.dataset.v476LiveBids)})}
async function refreshHostBidsV476(force=false){if(session?.role!=='host'||load().phase!=='P5'||!ROOM?.id||!SB||!ADMIN_TOKEN)return;if(!force&&Date.now()-HOST_BIDS_AT_V476<1400)return;HOST_BIDS_AT_V476=Date.now();const s=load();try{const {data,error}=await SB.rpc('get_project_auction_bids_admin',{p_admin_token:ADMIN_TOKEN,p_room_id:ROOM.id,p_round:s.round});if(error)throw error;HOST_BIDS_V476=Array.isArray(data)?data:[];HOST_BIDS_ERROR_V476='';patchHostLiveBidsV476()}catch(e){const m=String(e?.message||e);HOST_BIDS_ERROR_V476=/schema cache|PGRST202/i.test(m)?'Hãy chạy file SQL V4.7.6 trên Supabase rồi tải lại trang.':m;patchHostLiveBidsV476()}}

resolveProjects=async function(){const s=load();if(s.phase!=='P5')return;const out=[];for(const pr of projects(s)){const parts=eligibleProjectContenders(s,pr.id);if(!parts.length){out.push({round:s.round,projectId:pr.id,winner:null,bid:0,payout:0,competitive:false,solo:false,competitors:[]});continue}if(parts.length===1){out.push({round:s.round,projectId:pr.id,winner:parts[0],bid:0,payout:Number(pr.reward)||0,competitive:false,solo:true,competitors:parts});continue}const a=auctionState(s,pr.id);if(!a){alert(`Hãy MỞ ĐẤU THẦU cho ${pr.id} trước.`);return}if(!ROOM?.id){alert('Đấu thầu kín cần phòng online.');return}const {data,error}=await SB.rpc('resolve_project_auction_lowest_admin',{p_admin_token:ADMIN_TOKEN,p_room_id:ROOM.id,p_round:s.round,p_project_id:pr.id});if(error){const m=String(error.message||error);alert(/schema cache|PGRST202|Could not find the function/i.test(m)?`Máy chủ chưa cài hàm chốt giá thấp nhất. Hãy chạy file V4.7.6_SERVER_UPDATE_SUPABASE.sql rồi tải lại trang.`:`Không chốt được ${pr.id}: ${m}`);return}const row=Array.isArray(data)?data[0]:data;if(row?.status==='waiting'){alert(`${pr.id} còn thiếu giá của: ${(row.missing_players||[]).join(', ')}`);return}if(row?.status==='tie_rebid'){const root=ensureAuctionStateRoot(s);root[pr.id]={participants:row.participants||[],status:'open',bidRound:Number(row.bid_round)||((a.bidRound||1)+1)};logPush(s,`${pr.id} hòa giá thấp nhất. Chỉ ${root[pr.id].participants.join(', ')} đấu lại vòng #${root[pr.id].bidRound}.`);save(s);render();alert(`${pr.id} hòa giá thấp nhất. Chỉ các bên hòa tiếp tục gửi lại giá kín.`);return}const bid=Number(row?.winning_bid)||0;out.push({round:s.round,projectId:pr.id,winner:row?.winner||null,bid,payout:bid,competitive:true,solo:false,competitors:parts})}s.results=(s.results||[]).filter(r=>r.round!==s.round).concat(out);applyPhaseInterestV475(s,'P5','P6');s.phase='P6';s.timer.autoPassed=s.timer.autoPassed||{};s.timer.autoPassed.P5=true;logPush(s,'Host chốt kết quả P5: giá chào hợp lệ thấp nhất thắng.');save(s);render()};

