processMinuteBankInterestV475=function(s){if(!s.bank?.enabled)return false;const minute=Math.floor(activeElapsedMsNow(s)/BANK_MINUTE_MS_V475);let changed=false;for(const [name,p] of Object.entries(s.players||{})){const loan=normalizeBankLoanV475(p,s);if(!loan.active||loan.mode!=='minute'||p.bankrupt){loan.lastMinuteIndex=Math.max(Number(loan.lastMinuteIndex)||0,minute);continue}const previous=Math.max(0,Number(loan.lastMinuteIndex)||0),steps=Math.max(0,minute-previous);if(!steps)continue;const rate=bankInterestRateV475(s,'minute');let balance=loan.balance,total=0;for(let i=0;i<steps;i++){const add=roundMoneyV475(balance*rate);balance=roundMoneyV475(balance+add);total=roundMoneyV475(total+add)}loan.balance=balance;loan.lastMinuteIndex=minute;loan.lastRate=rate;loan.totalInterestAccrued=roundMoneyV475(loan.totalInterestAccrued+total);bankHistoryPushV475(loan,'interest',total,`${steps} phút · ${(rate*100).toFixed(2)}%/phút · cộng vào dư nợ`);logPush(s,`🏦 Dư nợ ${name} tăng ${total}M sau ${steps} phút.`);changed=true}return changed};
bankTrackerHtmlV475=function(name,s,auction=false){if(!s.bank?.enabled)return'';const p=s.players?.[name];if(!p)return'';const loan=normalizeBankLoanV475(p,s),cap=bankCapacityV475(s,p),rate=bankInterestRateV475(s,loan.active?loan.mode:s.bank.defaultMode),ratio=cap.maxDebt>0?Math.min(100,bankBalanceV475(p)/cap.maxDebt*100):0,open=bankBorrowAllowedV475(s)&&!p.bankrupt;if(auction)return`<div class="bank-auction-dock-v475"><div class="split"><div><b>🏦 Ngân hàng Cơ</b><div class="tiny muted">${loan.active?`Tổng nợ ${roundMoneyV475(loan.balance)}M · ${bankModeLabelV475(loan.mode)}`:`Còn có thể vay ${cap.available}M`}</div></div><button class="btn ${loan.active?'warn':'good'} openBankV475" ${open||loan.active?'':'disabled'}>${loan.active?'QUẢN LÝ NỢ':'VAY NGÂN HÀNG'}</button></div></div>`;return`<div class="card bank-card-v475"><div class="split"><div><div class="title">🏦 Ngân hàng Cơ</div><div class="muted tiny">Nút vay luôn sẵn ở P1–P3, P5 đấu thầu và phiên đấu giá P/s.</div></div><span class="badge">${loan.active?'ĐANG VAY':p.bankrupt?'PHÁ SẢN':'SẴN SÀNG'}</span></div>${loan.active?`<div class="bank-balance-live-v476" data-bank-live-balance-v476><small>TỔNG NỢ HIỆN TẠI · GỐC + LÃI</small>${roundMoneyV475(loan.balance)}M</div><div class="bank-meter-v475"><span style="width:${ratio.toFixed(1)}%"></span></div><div class="bank-stats-v475"><div class="bank-stat-v475">Gói lãi<b>${bankModeLabelV475(loan.mode)}</b></div><div class="bank-stat-v475">Lãi đã cộng vào nợ<b>${roundMoneyV475(loan.totalInterestAccrued)}M</b></div><div class="bank-stat-v475">Đã thanh toán<b>${roundMoneyV475(loan.totalPaid)}M</b></div><div class="bank-stat-v475">Tài sản khấu trừ<b>${roundMoneyV475(loan.totalCollateralLiquidated)}M</b></div><div class="bank-stat-v475">Tiền mặt hiện có<b>${roundMoneyV475(p.money)}M</b></div><div class="bank-stat-v475">Lãi hiện hành<b>${(rate*100).toFixed(2)}% ${loan.mode==='phase'?'/P':'/phút'}</b></div></div>`:`<div class="bank-balance-v475">Có thể vay ${cap.available}M</div><div class="tiny muted">Tài sản ròng ${cap.equity}M · trần dư nợ ${cap.maxDebt}M.</div>`}<button type="button" class="btn ${loan.active?'warn':'good'} big openBankV475" style="margin-top:9px" ${open||loan.active?'':'disabled'}>${loan.active?'XEM / THANH TOÁN KHOẢN NỢ':'VAY NGÂN HÀNG'}</button>${!open&&!loan.active?'<div class="tiny muted" style="margin-top:6px">Vay mới đang khóa ở giai đoạn này.</div>':''}</div>`};
bankModalHtmlV475=function(name,s){const p=s.players[name],loan=normalizeBankLoanV475(p,s),cap=bankCapacityV475(s,p),mode=loan.active?loan.mode:(BANK_MODAL_MODE_V475||s.bank.defaultMode||'minute'),rate=bankInterestRateV475(s,mode),canBorrow=bankBorrowAllowedV475(s)&&!p.bankrupt&&cap.available>0,canAll=Number(p.money)>=Number(loan.balance);return`<div class="bank-modal-backdrop-v475" id="bankModalV475" data-player="${esc(name)}"><div class="bank-modal-v475" role="dialog" aria-modal="true"><div class="split"><div><div class="title">🏦 Vay nợ Ngân hàng Cơ</div><div class="muted tiny">Dư nợ và lãi được cập nhật trực tiếp, không đóng bảng khi số liệu thay đổi.</div></div><button type="button" class="btn secondary closeBankV475">ĐÓNG</button></div><div class="bank-stats-v475" style="margin-top:10px"><div class="bank-stat-v475">Tài sản ròng<b data-bank-equity-v476>${cap.equity}M</b></div><div class="bank-stat-v475">Trần dư nợ 70%<b>${cap.maxDebt}M</b></div><div class="bank-stat-v475">Còn được vay<b>${cap.available}M</b></div></div><div class="bank-mode-grid-v475"><button type="button" class="bank-mode-v475 bankModeChoiceV475 ${mode==='minute'?'selected':''}" data-mode="minute" ${loan.active?'disabled':''}>⏱ Lãi theo phút realtime<br><span class="tiny muted">${(bankInterestRateV475(s,'minute')*100).toFixed(2)}%/phút · lãi cộng vào tổng dư nợ mỗi phút.</span></button><button type="button" class="bank-mode-v475 bankModeChoiceV475 ${mode==='phase'?'selected':''}" data-mode="phase" ${loan.active?'disabled':''}>🔁 Lãi theo mỗi lần đổi P<br><span class="tiny muted">${(bankInterestRateV475(s,'phase')*100).toFixed(2)}%/lần · lãi cộng vào tổng dư nợ khi đổi P.</span></button></div><div class="bank-warning-v475"><b>Lãi linh hoạt hiện tại: ${(rate*100).toFixed(2)}% ${mode==='phase'?'mỗi lần đổi P':'mỗi phút realtime'}.</b> Tổng nợ luôn gồm gốc + toàn bộ lãi đã phát sinh.</div>${canBorrow?`<div class="field" style="margin-top:10px"><label>Số tiền muốn vay (M)</label><input id="bankBorrowAmountV475" type="text" inputmode="numeric" autocomplete="off" placeholder="Tối đa ${cap.available}M"></div><div class="bank-quick-v475">${[5,10,50,100].map(v=>`<button type="button" class="btn secondary bankQuickBorrowV475" data-add="${v}">+${v}M</button>`).join('')}</div><button type="button" class="btn good big" id="bankBorrowConfirmV475">XÁC NHẬN VAY</button>`:`<div class="notice" style="margin-top:10px">${bankBorrowAllowedV475(s)?'Bạn đã dùng hết hạn mức hiện tại.':'Vay mới đang khóa ở P này; bạn vẫn có thể thanh toán khoản nợ.'}</div>`}${loan.active?`<div style="border-top:1px solid #dbe4f0;margin-top:12px;padding-top:12px"><div class="bank-balance-live-v476" data-bank-modal-balance-v476><small>TỔNG NỢ HIỆN TẠI · GỐC + LÃI</small>${roundMoneyV475(loan.balance)}M</div><div class="tiny muted">Lãi đã cộng: <b data-bank-interest-v476>${roundMoneyV475(loan.totalInterestAccrued)}M</b> · Tiền mặt: <b data-bank-cash-v476>${roundMoneyV475(p.money)}M</b></div><div class="field"><label>Số tiền bạn muốn thanh toán (M)</label><input id="bankRepayAmountV475" type="text" inputmode="decimal" autocomplete="off" placeholder="Nhập số tiền muốn trả"></div><div id="bankRepayFeedbackV476" class="bank-repay-feedback-v476"></div><div class="grid grid-2"><button type="button" class="btn warn big" id="bankRepayConfirmV475">THANH TOÁN SỐ ĐÃ NHẬP</button><button type="button" class="btn good big ${canAll?'':'bank-payall-disabled-v476'}" id="bankRepayAllV475" ${canAll?'':'disabled'}>${canAll?`TRẢ HẾT ${roundMoneyV475(loan.balance)}M`:`THIẾU ${roundMoneyV475(loan.balance-Number(p.money))}M ĐỂ TRẢ HẾT`}</button></div><div class="tiny muted" style="margin-top:7px">Thanh toán một phần có thể dùng cơ chế tiền âm/khấu trừ tài sản như luật hiện hành. Nút xanh chỉ tất toán khi tiền mặt đủ toàn bộ dư nợ.</div></div>`:''}</div></div>`};
function sanitizeBankDecimalV476(el){if(!el)return'';let v=String(el.value||'').replace(',','.').replace(/[^0-9.]/g,''),p=v.split('.');if(p.length>2)v=p.shift()+'.'+p.join('');p=v.split('.');if(p[1]?.length>1)v=p[0]+'.'+p[1].slice(0,1);el.value=v;return v}
repayBankV475=async function(name,all=false){const s=load(),p=s.players?.[name],loan=normalizeBankLoanV475(p,s),input=document.getElementById('bankRepayAmountV475'),feedback=document.getElementById('bankRepayFeedbackV476'),raw=all?loan.balance:Number(sanitizeBankDecimalV476(input)),amount=Math.min(loan.balance,roundMoneyV475(raw));if(!loan.active)return;if(all&&Number(p.money)<Number(loan.balance)){if(feedback)feedback.textContent='Tiền mặt chưa đủ để dùng nút trả hết.';return}if(!all&&(!Number.isFinite(amount)||amount<=0)){if(feedback)feedback.textContent='Chưa có giao dịch: hãy nhập số tiền muốn thanh toán.';input?.focus({preventScroll:true});return}const ok=await uiConfirmV46({title:all?'TẤT TOÁN KHOẢN VAY?':'THANH TOÁN KHOẢN VAY?',rows:[['Dư nợ hiện tại',`${roundMoneyV475(loan.balance)}M`],['Số tiền trả',`${amount}M`],['Còn lại sau trả',`${roundMoneyV475(loan.balance-amount)}M`]],message:'Số tiền được trừ đúng vào tổng nợ hiện tại gồm cả gốc và lãi.',confirmText:all?'TRẢ HẾT':'THANH TOÁN'});if(!ok)return;const fresh=load(),fp=fresh.players[name],before=normalizeBankLoanV475(fp,fresh),actual=Math.min(amount,before.balance);if(all&&Number(fp.money)<Number(before.balance)){alert('Số dư vừa thay đổi và không còn đủ để trả hết.');patchBankLiveV476();return}collectBankChargeV475(fresh,name,actual,'repayment');const fl=normalizeBankLoanV475(fp,fresh);fl.balance=roundMoneyV475(Math.max(0,fl.balance-actual));fl.principal=roundMoneyV475(Math.min(fl.principal,fl.balance));fl.totalPaid=roundMoneyV475(fl.totalPaid+actual);bankHistoryPushV475(fl,'repay',actual,'Người chơi chủ động thanh toán');if(fl.balance<=0&&!fp.bankrupt){fl.active=false;fl.status='closed';fl.balance=0;fl.principal=0;fl.closedAt=Date.now();logPush(fresh,`✅ ${name} đã tất toán khoản vay Ngân hàng Cơ.`)}else logPush(fresh,`🏦 ${name} thanh toán ${actual}M, còn nợ ${fl.balance}M.`);closeBankModalV475();save(fresh);render()};
const _bindBankModalV476Base=bindBankModalV475;
bindBankModalV475=function(name){_bindBankModalV476Base(name);const old=document.getElementById('bankRepayAmountV475');if(old){const input=old.cloneNode(true);old.replaceWith(input);input.addEventListener('input',()=>{sanitizeBankDecimalV476(input);const f=document.getElementById('bankRepayFeedbackV476');if(f)f.textContent=''})}};
function patchBankLiveV476(){const modal=document.getElementById('bankModalV475'),s=load(),name=modal?.dataset.player||(session?.role==='player'?session.name:null),p=s.players?.[name];if(!p)return;const loan=normalizeBankLoanV475(p,s),balance=roundMoneyV475(loan.balance),cash=roundMoneyV475(p.money),canAll=cash>=balance;document.querySelectorAll('[data-bank-live-balance-v476]').forEach(b=>b.innerHTML=`<small>TỔNG NỢ HIỆN TẠI · GỐC + LÃI</small>${balance}M`);if(!modal)return;const b=modal.querySelector('[data-bank-modal-balance-v476]');if(b)b.innerHTML=`<small>TỔNG NỢ HIỆN TẠI · GỐC + LÃI</small>${balance}M`;const i=modal.querySelector('[data-bank-interest-v476]');if(i)i.textContent=`${roundMoneyV475(loan.totalInterestAccrued)}M`;const c=modal.querySelector('[data-bank-cash-v476]');if(c)c.textContent=`${cash}M`;const all=modal.querySelector('#bankRepayAllV475');if(all){all.disabled=!canAll;all.classList.toggle('bank-payall-disabled-v476',!canAll);all.textContent=canAll?`TRẢ HẾT ${balance}M`:`THIẾU ${roundMoneyV475(balance-cash)}M ĐỂ TRẢ HẾT`}}

/* ---------- Final valuation uses end-of-game rates, then debt ---------- */
function finalInventoryValueV476(s,p){const prices=bankPriceMapV475(s),units=[];for(const k of RESOURCE_KEYS)for(let i=0,n=Math.max(0,Math.floor(Number(p.res?.[k])||0));i<n;i++)units.push(prices[k]);units.sort((a,b)=>b-a);return roundMoneyV475(units.reduce((sum,v,i)=>sum+v*(i<9?1:.3),0))}
ranking=function(s){const rows=Object.entries(s.players||{}).map(([name,p])=>{const resCount=Object.values(p.res||{}).reduce((a,b)=>a+(Number(b)||0),0),resValue=finalInventoryValueV476(s,p),debt=bankBalanceV475(p),projectRevenue=(p.wins||[]).reduce((a,w)=>a+(Number(w.reward)||0),0),tradeCount=(s.trades||[]).filter(t=>t.status==='accepted'&&(t.buyer===name||t.seller===name||t.from===name||t.to===name)).length,total=roundMoneyV475((Number(p.money)||0)+resValue-debt);return{name,cash:Number(p.money)||0,resCount,resValue,total,wins:(p.wins||[]).length,projectRevenue,auctionCost:0,tradeCount,company:p.company,debt,bankrupt:!!p.bankrupt}}).sort((a,b)=>Number(a.bankrupt)-Number(b.bankrupt)||b.total-a.total||b.cash-a.cash||b.wins-a.wins||a.name.localeCompare(b.name,'vi'));let prevKey=null,prevRank=0;rows.forEach((r,i)=>{const key=`${r.bankrupt?'B':'A'}:${r.total}`;if(i===0||key!==prevKey)prevRank=i+1;r.rank=prevRank;prevKey=key});return rows};
