finalView=function(s,viewer){const html=_finalViewV476Base(s,viewer),box=document.createElement('div');box.innerHTML=html;const shell=box.querySelector('.exec-shell');shell?.classList.add('v476-final');const podium=box.querySelector('.exec-podium');podium?.classList.add('v476-podium');const note=[...box.querySelectorAll('.footer-note')].find(x=>x.textContent.includes('Công thức'));if(note)note.innerHTML='<b>Công thức V4.7.6:</b> Tiền mặt + tài nguyên quy đổi theo <b>tỷ giá ở thời điểm kết game</b> (9 đơn vị giá trị cao nhất tính 100%, phần còn lại tính 30%) − toàn bộ dư nợ Ngân hàng Cơ. Đồng tổng tài sản được đồng hạng.';return box.innerHTML};

