function playerBlockedAtPhaseV476(name,s){const p=s.players?.[name];if(!p||p.bankrupt)return false;if(s.phase==='P4'){const ids=playerTargetsV475(p,s);return !ids.length||!ids.some(pid=>canLockProjectV475(p,s,pid)||projectDecisionV475(p,pid)==='locked')}if(s.phase==='P5')return !lockedProjectIdsV475(p,s).some(pid=>enough(p,projectById(s,pid)?.need||{}));return false}
function phaseGateV476(name,s){if(!playerBlockedAtPhaseV476(name,s))return'';const noTarget=!playerTargetsV475(s.players[name],s).length;return`<div class="phase-gate-v476"><div class="phase-gate-card-v476"><div class="gate-icon">${noTarget?'📭':'⛔'}</div><h2>${noTarget?'BẠN KHÔNG CÓ DỰ ÁN NÀO ĐẤU THẦU':'BẠN KHÔNG ĐỦ ĐIỀU KIỆN ĐẤU THẦU'}</h2><div>${s.phase==='P4'?'Bạn không thể thao tác trong P4.':'Các doanh nghiệp đủ điều kiện đang đấu thầu và thanh toán dự án.'}</div><div class="muted" style="margin-top:8px">Màn hình sẽ tự mở lại khi Host chuyển sang giai đoạn công bố kết quả.</div></div></div>`}
function p7DismissKeyV476(s){return`tt_v476_p7_seen:${ROOM?.code||roomInfo()?.code||'offline'}:R${s.round}`}
function p7ResultsOverlayV476(s){if(s.phase!=='P7'||sessionStorage.getItem(p7DismissKeyV476(s))==='1')return'';const rows=(s.results||[]).filter(r=>Number(r.round)===Number(s.round)&&r.winner).slice().sort((a,b)=>resultDisplayPayoutV475(b,s)-resultDisplayPayoutV475(a,s));if(!rows.length)return'';return`<div class="p7-overlay-v476" id="p7OverlayV476"><div class="p7-card-v476" role="dialog" aria-modal="true"><div class="p7-title-v476">🏆 KẾT QUẢ THỊ TRƯỜNG ${s.round}</div><div class="p7-sub-v476">Danh sách trúng dự án · xếp theo số tiền nhận từ cao xuống thấp</div>${rows.map((r,i)=>{const defeated=(r.competitors||[]).filter(n=>n!==r.winner),money=resultDisplayPayoutV475(r,s);return`<div class="p7-result-v476"><span class="rank">${i+1}</span><div><b>${esc(r.winner)} · ${esc(r.projectId)}</b><div class="tiny muted">${r.solo||!r.competitive?'Trúng thầu một mình':`Thắng ${defeated.length?defeated.map(esc).join(' · '):'các doanh nghiệp cạnh tranh'} với giá ${Number(r.bid)||0}M`}</div></div><span class="money">${money}M</span></div>`}).join('')}<button class="btn good big" id="dismissP7V476" style="margin-top:12px;width:100%">TÔI ĐÃ XEM KẾT QUẢ</button></div></div>`}
function bindP7OverlayV476(){const b=document.getElementById('dismissP7V476');if(b)b.onclick=()=>{sessionStorage.setItem(p7DismissKeyV476(load()),'1');document.getElementById('p7OverlayV476')?.remove()}}

const _playerViewV476Base=playerView;
playerView=function(name){const s=load();let html=_playerViewV476Base(name);if(s.gameOver||s.specialAuction?.active)return html;const box=document.createElement('div');box.innerHTML=html;const timer=box.querySelector('.timer-card');if(timer){timer.classList.add('player-timer-v476');timer.remove()}const main=box.querySelector('.app > .grid.grid-2'),left=main?.children[0],asset=left?.querySelector('.money')?.closest('.card');if(s.phase==='P4'&&asset){const status=[...left.children].find(x=>x.querySelector?.('.phase')),action=status?.querySelector('.v475-p4-list,.v475-static-stage');if(action){const card=document.createElement('div');card.className='card p4-priority-v476';card.appendChild(action);asset.insertAdjacentElement('afterend',card)}}if(matchMedia('(max-width: 767px)').matches)box.querySelectorAll('.v475-project').forEach(card=>{const pid=card.dataset.v475Project||card.dataset.project,open=projectExpandedV475(name,s,pid);card.classList.toggle('collapsed',!open);const h=card.querySelector('.projectExpandV475'),c=card.querySelector('.v475-project-chevron');h?.setAttribute('aria-expanded',open?'true':'false');if(c){c.textContent=open?'−':'＋';c.setAttribute('aria-label',open?'Thu gọn':'Mở chi tiết');c.title=open?'Thu gọn':'Mở chi tiết'}});const app=box.querySelector('.app');if(app){app.insertAdjacentHTML('beforeend',phaseGateV476(name,s));app.insertAdjacentHTML('beforeend',p7ResultsOverlayV476(s))}return box.innerHTML};
const _hostViewV476Base=hostView;
hostView=function(){const s=load(),html=_hostViewV476Base();if(s.gameOver||s.specialAuction?.active)return html;const box=document.createElement('div');box.innerHTML=html;const right=box.querySelector('.host-dashboard')?.children?.[1];if(right&&!right.querySelector('.host-bank-overview-v476')){const secrets=[...right.children].find(x=>x.querySelector?.('#toggleHostSecrets'));if(secrets)secrets.insertAdjacentHTML('afterend',hostBankOverviewV476(s));else right.insertAdjacentHTML('afterbegin',hostBankOverviewV476(s))}box.querySelector('.app')?.insertAdjacentHTML('beforeend',p7ResultsOverlayV476(s));return box.innerHTML};
const _observerViewV476Base=observerView;
observerView=function(){const s=load(),html=_observerViewV476Base();if(s.gameOver||s.specialAuction?.active)return html;const box=document.createElement('div');box.innerHTML=html;box.firstElementChild?.insertAdjacentHTML('beforeend',p7ResultsOverlayV476(s));return box.innerHTML};

/* ---------- Final binding composition ---------- */
const _bindPlayerV476Base=bindPlayer;
bindPlayer=function(name){_bindPlayerV476Base(name);document.body.classList.toggle('v476-phase-locked',playerBlockedAtPhaseV476(name,load()));bindP7OverlayV476()};
const _bindHostV476Base=bindHost;
bindHost=function(){_bindHostV476Base();document.body.classList.remove('v476-phase-locked');bindP7OverlayV476();refreshHostBidsV476(false)};
const _bindObserverV476Base=bindObserver;
bindObserver=function(){_bindObserverV476Base();document.body.classList.remove('v476-phase-locked');bindP7OverlayV476()};
const _timerTickV476Base=timerTick;
timerTick=function(){const out=_timerTickV476Base();patchBankLiveV476();refreshHostBidsV476();return out};
const _renderV476Base=render;
render=function(){const out=_renderV476Base();patchBankLiveV476();return out};

const _loginViewV476Base=loginView;
loginView=function(){return _loginViewV476Base().replace(/V4\.7\.5 Multiplayer/g,'V4.7.6.3 Multiplayer')};
document.title=document.title.replace(/V4\.7\.5 Multiplayer/g,'V4.7.6.3 Multiplayer');
